struct MobileDecision: Codable, Equatable, Identifiable, Sendable {
    struct Option: Codable, Equatable, Sendable {
        var label: String
        var description: String?
        var recommended: Bool?
    }

    var taskId: String
    var from: String?
    var id: String
    var question: String
    var context: String?
    var options: [Option]
}

